import{_ as a,o as e,c as i,a3 as l}from"./chunks/framework.D1iekJsc.js";const m=JSON.parse('{"title":"30 分钟通关","description":"从零到 MiniTavern 收到本地模型第一条回复：选 Ollama 或 LM Studio、装模型、局域网连 App，约 30 分钟。","frontmatter":{"title":"30 分钟通关","description":"从零到 MiniTavern 收到本地模型第一条回复：选 Ollama 或 LM Studio、装模型、局域网连 App，约 30 分钟。","head":[["meta",{"name":"keywords","content":"酒馆,AI酒馆,Ai酒馆,迷你酒馆,超迷你酒馆,MiniTavern,AI伙伴,AI朋友,Ai本地聊天,AI本地聊天,Silly Tavern,SillyTavern,手机玩Silly Tavern,Silly Tavern手机版,Silly Tavern安卓,Silly Tavern苹果,AI角色扮演,角色卡,角色扮演,AI聊天,手机AI,离线AI,AI剧情,本地大模型,本地模型,Ollama,LM Studio,世界书,正则,BYOK,用户手册,教程,character card,AI roleplay,AI companion,tavern AI"}],["meta",{"property":"og:title","content":"30 分钟通关 · MiniTavern Docs"}],["meta",{"property":"og:description","content":"从零到 MiniTavern 收到本地模型第一条回复：选 Ollama 或 LM Studio、装模型、局域网连 App，约 30 分钟。"}],["meta",{"property":"og:url","content":"https://minitavern.github.io/ultra_guides/quickstart"}],["link",{"rel":"canonical","href":"https://minitavern.github.io/ultra_guides/quickstart"}]]},"headers":[],"relativePath":"quickstart.md","filePath":"quickstart.md","lastUpdated":1787117554000}'),r={name:"quickstart.md"};function o(n,t,s,d,p,h){return e(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="_30-分钟通关" tabindex="-1">30 分钟通关 <a class="header-anchor" href="#_30-分钟通关" aria-label="Permalink to &quot;30 分钟通关&quot;">​</a></h1><p>目标：从零到在 MiniTavern 里收到本地模型的第一条回复。</p><table tabindex="0"><thead><tr><th>步骤</th><th>大约用时</th><th>做什么</th></tr></thead><tbody><tr><td>1</td><td>0–5 min</td><td>选工具：Ollama 或 LM Studio</td></tr><tr><td>2</td><td>5–15 min</td><td>安装并下载一个小模型</td></tr><tr><td>3</td><td>15–20 min</td><td>开启局域网 / Local Server</td></tr><tr><td>4</td><td>20–25 min</td><td>查电脑局域网 IP</td></tr><tr><td>5</td><td>25–30 min</td><td>在 MiniTavern 新建连接并测连</td></tr></tbody></table><hr><h2 id="step-1-选工具" tabindex="-1">Step 1：选工具 <a class="header-anchor" href="#step-1-选工具" aria-label="Permalink to &quot;Step 1：选工具&quot;">​</a></h2><ul><li><strong>想最快</strong>：选 <a href="./ollama/install">Ollama</a> 或 <a href="./lmstudio/install">LM Studio</a></li><li><strong>角色扮演向</strong>：可后续换 <a href="./koboldcpp/install">KoboldCPP</a></li><li><strong>已有 GGUF</strong>：可用 <a href="./llamacpp/install">llama.cpp</a></li></ul><p>完整对比见 <a href="./local/tools">工具总览</a>。下面以 <strong>Ollama</strong> 为例写通关步骤；其它工具把「拉模型 / 开服务」换成对应章节即可，第 5 步相同。</p><hr><h2 id="step-2-安装并拉一个小模型" tabindex="-1">Step 2：安装并拉一个小模型 <a class="header-anchor" href="#step-2-安装并拉一个小模型" aria-label="Permalink to &quot;Step 2：安装并拉一个小模型&quot;">​</a></h2><ol><li>按 <a href="./ollama/install">Ollama 安装</a> 装好。</li><li>打开终端，执行（示例模型，体积相对小，适合验证通路）：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><ol start="3"><li>确认本机可用：</li></ol><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ollama</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> llama3.2:3b</span></span></code></pre></div><p>能对话后输入 <code>/bye</code> 退出即可。更多模型选择见 <a href="./ollama/models">下载与选择模型</a>。</p><hr><h2 id="step-3-开启局域网访问" tabindex="-1">Step 3：开启局域网访问 <a class="header-anchor" href="#step-3-开启局域网访问" aria-label="Permalink to &quot;Step 3：开启局域网访问&quot;">​</a></h2><p>按 <a href="./ollama/lan">开启局域网访问</a> 设置 <code>OLLAMA_HOST=0.0.0.0</code>，并放行防火墙端口 <strong>11434</strong>。</p><p>完成后，在<strong>电脑本机</strong>浏览器访问（应有响应，不一定是漂亮网页）：</p><p><code>http://127.0.0.1:11434</code></p><hr><h2 id="step-4-查电脑局域网-ip" tabindex="-1">Step 4：查电脑局域网 IP <a class="header-anchor" href="#step-4-查电脑局域网-ip" aria-label="Permalink to &quot;Step 4：查电脑局域网 IP&quot;">​</a></h2><ul><li><strong>Windows</strong>：<code>Win + R</code> → <code>cmd</code> → 输入 <code>ipconfig</code>，找「无线局域网适配器」下的 <strong>IPv4 地址</strong>（形如 <code>192.168.x.x</code>）。</li><li><strong>macOS</strong>：系统设置 → 网络 → 当前 Wi‑Fi → 详情里的 IP；或终端执行 <code>ipconfig getifaddr en0</code>。</li></ul><p>记下这个 IP，后面记作 <code>YOUR_PC_IP</code>。</p><hr><h2 id="step-5-在-minitavern-里配置" tabindex="-1">Step 5：在 MiniTavern 里配置 <a class="header-anchor" href="#step-5-在-minitavern-里配置" aria-label="Permalink to &quot;Step 5：在 MiniTavern 里配置&quot;">​</a></h2><ol><li>打开 App → <strong>设置 → 模型 → 模型连接 → 新建</strong>。</li><li>平台选 <strong>自定义 / OpenAI 兼容</strong>（以 App 内实际选项名为准）。</li><li>填写：</li></ol><table tabindex="0"><thead><tr><th>字段</th><th>示例（Ollama）</th></tr></thead><tbody><tr><td>Base URL</td><td><code>http://YOUR_PC_IP:11434/v1</code></td></tr><tr><td>API Key</td><td>可留空或填任意占位（本地通常不校验）</td></tr><tr><td>模型名</td><td><code>llama3.2:3b</code>（与 <code>ollama list</code> 一致）</td></tr></tbody></table><ol start="4"><li>保存并 <strong>测连</strong>；成功后设为默认，导入角色卡开聊。</li></ol><p>完整界面说明见 <a href="./connect-app/minitavern">在 MiniTavern 中配置</a>。</p><hr><h2 id="失败了" tabindex="-1">失败了？ <a class="header-anchor" href="#失败了" aria-label="Permalink to &quot;失败了？&quot;">​</a></h2><ul><li>测连失败、超时、空白回复 → 打开 <a href="./troubleshoot">排错对照表</a></li><li>最常见错误：<strong>Base URL 写成了 <code>localhost</code></strong>，或手机与电脑不在同一 Wi‑Fi</li></ul>',32)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
